cd /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad && cat > p4rev_decldiff.py <<'EOF'
import re,sys
def decls(path):
    src=open(path).read()
    # strip doc comments and comments
    src=re.sub(r'/-.*?-/', '', src, flags=re.S)
    lines=src.split('\n')
    out={}; cur=None; buf=[]; idx=0
    kw=re.compile(r'^(theorem|def|inductive|structure|instance|example|abbrev|attribute|namespace|end|#eval|#guard_msgs)\b')
    blocks=[]
    for l in lines:
        if kw.match(l):
            if cur is not None: blocks.append((cur,'\n'.join(buf)))
            cur=l; buf=[l]
        elif cur is not None: buf.append(l)
    if cur is not None: blocks.append((cur,'\n'.join(buf)))
    res={}
    n=0
    for head,body in blocks:
        m=re.match(r'^(theorem|def|inductive|structure|instance|abbrev)\s+(\S+)',head)
        if m and m.group(1) in('theorem',):
            name=m.group(2); stmt=body.split(':=')[0]
        elif m:
            name=m.group(2) if m.group(1)!='instance' else 'instance#'+str(n); stmt=body
            if m.group(1)=='instance': n+=1
        elif head.startswith('example'):
            name='example#'+str(n); n+=1; stmt=body.split(':= by')[0]
        else: continue
        res[name]=' '.join(stmt.split())
    return res
a=decls(sys.argv[1]); b=decls(sys.argv[2])
for k in a:
    if k not in b: print('REMOVED',k)
for k in b:
    if k not in a: print('ADDED',k)
for k in a:
    if k in b and a[k]!=b[k]: print('CHANGED',k)
EOF
python3 -I p4rev_decldiff.py mm02_p3.lean p4rev_c_25ee0aa.lean

